		char info[1024] = { 0 };
		sprintf(info, "查询飞控当前航线失败: %s ", Mission::result_str(result));
		printf("%s %s \n", FcowUtil::current_time(), info);
		return -5;
	}
	printf("%s 打印飞控系统中的飞行任务内容-结束 \n", FcowUtil::current_time());
